// System generated embedded SQLite database fallback
const DB_BASE64 = "";

export function getEmbeddedDbBytes(): Uint8Array {
  const binaryString = atob(DB_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
